using System;
using System.Collections.Generic;

namespace murumsWiiModStudio
{
    internal sealed class HelpTopic
    {
        public string Title, Summary, Route, Note;
        public string[] Steps;
        public bool IncludeLinks;
        public override string ToString()
        {
            return Title;
        }
    }

    internal static class StudioHelpTopics
    {
        static HelpTopic T(string de, string en, string sd, string se, string route, string[] d, string[] e, string nd, string ne)
        {
            return new HelpTopic
            {
                Title = L.T(de, en),
                Summary = L.T(sd, se),
                Route = route,
                Steps = L.IsGerman ? d : e,
                Note = L.T(nd, ne)
            };
        }

        public static List<HelpTopic> All()
        {
            var topics = new List<HelpTopic>
            {
                T("Schnellstart", "Quick start", "In vier Schritten vom Original zur getesteten Kopie.", "Four steps from the original to a tested copy.", "Öffnen / Open  →  Bearbeiten / Edit  →  Vorschau / Preview  →  Kopie / Copy", new[] { "Quelle sichern|Lege eine Sicherung deines Custom Packs an.", "Tool wählen|Öffne unter Tools den passenden Editor und lade deine Quelldateien.", "Änderung prüfen|Nutze die Vorschau. Übernimm nur die gewünschten Änderungen.", "Kopie testen|Speichere separat, übernimm sie in dein Testing-Pack und starte das Spiel neu." }, new[] { "Back up the source|Keep a backup of your custom pack.", "Choose a tool|Open the appropriate editor under Tools and load your source files.", "Review the change|Use its preview and apply only the changes you want.", "Test the copy|Save separately, install in your testing pack and restart the game." }, "Eine Vorschau bestätigt nicht automatisch die Darstellung im Spiel.", "A preview does not automatically confirm the in-game appearance."),
                T("Menühintergründe", "Menu backgrounds", "Bilder oder GIFs für die Menüs deines Packs.", "Pictures or GIFs for your pack's menus.", "Tools > MKWii RR-Backgrounds Tool", new[] { "Pack auswählen|Unter Ordner & Qualität deinen Custom-Pack-Ordner wählen.", "Bild zuordnen|Titel / Lizenz, Singleplayer oder Multiplayer wählen; Bild oder GIF laden und Vorschau prüfen.", "Kopien erstellen|Den Builder unten verwenden. Ergebnisse aus RR_EDITED nach Sicherung ins Pack übernehmen." }, new[] { "Select the pack|Choose your custom pack in Folders & quality.", "Assign artwork|Choose Title / License, Single Player or Multiplayer. Load artwork and inspect the preview.", "Build copies|Use the bottom build button. Back up pack files before installing results from RR_EDITED." }, "Spracharchive nur verwenden, wenn dein Pack sie enthält.", "Use language archives only when your pack contains them."),
                T("Globus, Himmel & Modelle", "Globe, sky & models", "Farben, Hintergrundbild und sichtbare Modelle einstellen.", "Set colours, background artwork and model visibility.", "MKWii RR-Backgrounds > Other UI", new[] { "Bereich wählen|Globus & Himmel oder 3D-Modelle öffnen.", "Darstellung einstellen|Farben wählen, Foto/GIF laden oder Modelle per Häkchen sichtbar lassen. Sternmuster werden gekachelt.", "Vorschau & Kopie|Zuschnitt und schematische Auswahl prüfen; anschließend unten erstellen." }, new[] { "Choose a section|Open Globe & sky or 3D models.", "Set appearance|Choose colours or a photo/GIF. Checked models remain visible. Star patterns tile.", "Preview and build|Review fitting and the schematic setup, then build at the bottom." }, "Die 3D-Vorschau ist schematisch. Gemeinsame Modelle können mehrere Menüs verändern.", "The 3D preview is schematic. Shared models may affect several menus."),
                T("Race HUD: Bilder & Zahlen", "Race HUD: pictures & numbers", "Platzierung, Zeit, Runden, Score und weitere HUD-Bilder.", "Placement, time, laps, score and other HUD artwork.", "Tools > MKWii Race HUD Tool", new[] { "Archive laden|Race.szs und die tatsächlich verwendete Sprachdatei laden. Zusätzliche RR-Ressourcen liegen in RaceAssets.szs.", "Element bearbeiten|Kategorie wählen. Bild ersetzen oder Colours nutzen. Number font erzeugt Zahlen aus einer TTF; Umfang und Vorschau prüfen.", "Änderungen speichern|Pending replacements prüfen. Save edited archives unten schreibt Kopien in HUD_EDITED." }, new[] { "Load archives|Load Race.szs and the language archive your game uses. Extra RR resources are in RaceAssets.szs.", "Edit an element|Choose a category. Replace artwork or use Colours. Number font generates TTF digits; review scope and preview.", "Save changes|Review Pending replacements. Save edited archives at the bottom writes copies to HUD_EDITED." }, "Font Changer bearbeitet allgemeine Schriften. HUD-Zahlen gehören hierher. Spielmaterialien können Farben verändern.", "Font Changer edits general fonts. HUD digits belong here. Game materials may change colours."),
                T("Minimap-Farben", "Minimap colours", "Grundfarbe, Transparenz und Farbverlauf der Karte.", "Map base colour, transparency and corner gradient.", "MKWii Race HUD > Map colours", new[] { "Map-Layout wählen|Race.szs laden und Map colours öffnen.", "Farben einstellen|Map base oder eine Ecke wählen. Choose colour und Opacity ändern; Uniform colour setzt einen einheitlichen Verlauf.", "Übernehmen|Apply map changes klicken, dann im Race HUD unten speichern. Rückgängig über Pending replacements." }, new[] { "Choose the map layout|Load Race.szs and open Map colours.", "Set colours|Select Map base or a corner. Adjust Choose colour and Opacity; Uniform colour resets the gradient.", "Apply|Click Apply map changes, then save at the bottom of Race HUD. Undo via Pending replacements." }, "Die Musterstrecke ist eine Illustration, nicht die Geometrie deiner Strecke.", "The sample track is illustrative, not your course geometry."),
                T("Input Viewer", "Input Viewer", "Tasten, Steuerkreuz und Stick getrennt gestalten.", "Style buttons, D-pad and stick separately.", "MKWii Race HUD > Input viewer", new[] { "Ressourcen laden|RaceAssets.szs direkt öffnen oder mit Add archive hinzufügen.", "Zustand wählen|On/Off-Dateien sind getrennte gedrückte und losgelassene Zustände. Bild ersetzen oder Colours wählen.", "Gemeinsam prüfen|Preview category zeigt die aktuellen Texturen. Danach Änderungen unten speichern." }, new[] { "Load resources|Open RaceAssets.szs directly or use Add archive.", "Choose a state|On/off files are separate pressed and released states. Replace the picture or choose Colours.", "Review together|Preview category shows current textures. Save changes at the bottom." }, "Die Übersicht zeigt Texturen, keine live reagierende Controller-Anzeige.", "The overview shows textures, not a live controller display."),
                T("Schriften ändern", "Change fonts", "Allgemeine Spielschriften mit einer TTF ersetzen.", "Replace general game fonts using a TTF.", "Tools > MKWii Font Changer Tool", new[] { "Schrift auswählen|Font.szs öffnen, darin eine Textschrift wählen und TTF laden.", "Stil prüfen|Füllung, Kontur und Hinting einstellen. Preview Latin replacement anwenden; Sample text und Font atlas prüfen.", "Kopie speichern|Weitere Schriften bei Bedarf einzeln bearbeiten, dann Save font copy unten verwenden." }, new[] { "Choose a font|Open Font.szs, select a text font inside it and load a TTF.", "Review styling|Set fill, outline and hinting. Apply Preview Latin replacement; inspect Sample text and Font atlas.", "Save a copy|Edit other fonts individually as needed, then use Save font copy at the bottom." }, "Fehlende TTF-Zeichen behalten ihr Original. Graustufenformate können keine beliebigen Farben speichern.", "Missing TTF characters keep their originals. Grayscale formats cannot store arbitrary colours."),
                T("Menütexte", "Menu texts", "Nachrichten finden, bearbeiten und lesbar prüfen.", "Find, edit and preview messages.", "Tools > MKWii Menu Text Tool", new[] { "Texte öffnen|Spracharchiv oder BMG öffnen und Ressource wählen.", "Nachricht ändern|Nach ID oder Text suchen, Textspalte bearbeiten. Die Vorschau zeigt Zeilenumbrüche.", "Kopie speichern|Save edited copy schreibt die Änderungen separat. Länge anschließend im Spiel prüfen." }, new[] { "Open messages|Open a language archive or BMG and choose its resource.", "Edit a message|Search by ID or text and edit the text column. The preview shows line breaks.", "Save a copy|Save edited copy writes changes separately. Check text length in game." }, "Steuerzeichen für Farben, Symbole und Variablen erhalten. Die Vorschau nutzt eine Systemschrift.", "Preserve colour, symbol and variable escapes. The preview uses a system font."),
                T("Musik & Loops", "Music & loops", "Loopbereich sehen und den Übergang anhören.", "See the loop range and listen to its seam.", "Tools > MKWii Music & Loops Tool", new[] { "Audio laden|PCM WAV öffnen oder andere Formate mit FFmpeg konvertieren.", "Loop setzen|Start und Ende in Samples wählen. Die Wellenform markiert den Bereich; Preview loop spielt ihn wiederholt.", "Exportieren|Save looped WAV verwenden. Im BRSTM-Konverter die Loopmarkierungen behalten." }, new[] { "Load audio|Open PCM WAV or convert other formats with FFmpeg.", "Set the loop|Choose sample start/end. The waveform marks the range; Preview loop repeats it.", "Export|Use Save looped WAV. Keep loop markers when converting to BRSTM." }, "Das Ende ist exklusiv. Musik für die letzte Runde kann eine separate Datei benötigen.", "The end is exclusive. Final-lap music may need a separate file."),
                T("Theme-Projekte", "Theme projects", "Fertige Änderungen zu einem Pack zusammenstellen.", "Collect finished edits into one output pack.", "Tools > MKWii Theme Project Tool", new[] { "Projekt anlegen|Custom-Pack-Ordner als Basis wählen.", "Dateien zuordnen|Add edited file: erst Originalziel im Pack, dann Ersatzdatei wählen. Preview selected file prüfen.", "Speichern & bauen|Projekt als .mtheme speichern; Build theme folder erstellt die Ausgabe." }, new[] { "Create a project|Choose the custom pack as the base.", "Map files|Add edited file: choose the original target, then the replacement. Inspect Preview selected file.", "Save and build|Save the .mtheme project; Build theme folder creates the output." }, "Dateien bleiben verknüpft. Das Projekt speichert nicht automatisch die Einstellungen aller Editoren.", "Files remain linked. Projects do not automatically capture every editor's settings."),
                T("Archive vergleichen", "Compare archives", "Gewünschte Änderungen gezielt übernehmen.", "Select which changed resources to keep.", "Tools > MKWii Archive Compare Tool", new[] { "Versionen laden|Base ist der Ausgangsstand; Edited enthält die gewünschten Änderungen.", "Unterschiede prüfen|Compare entries wählen. Eine Ressource anklicken, um beide Versionen nebeneinander zu sehen.", "Auswahl speichern|Nur gewünschte Ressourcen anhaken und Save selected changes verwenden." }, new[] { "Load versions|Base is the state to keep; Edited supplies desired changes.", "Review differences|Choose Compare entries. Select a resource to see both versions side by side.", "Save selection|Check only desired resources and use Save selected changes." }, "Es werden ganze Ressourcen ersetzt. Hinzugefügte oder entfernte Pfade werden nicht automatisch zusammengeführt.", "Whole resources are replaced. Added or removed paths are not merged automatically."),
                T("Dateien & Zuordnung", "Files & destinations", "Die wichtigsten Archive auf einen Blick.", "Key archives at a glance.", "Custom pack", new[] { "Menüs|Title.szs: Titel/Lizenz. MenuSingle.szs: Einzelspieler. MenuMulti.szs: Multiplayer.", "Globus & Hintergrund|Globe.szs: Online-Menüs. Earth.szs: Globusszene/Himmel. globe.arc: Globusfarben. BackModel.szs: Menümodelle.", "HUD & Schrift|Race.szs und Sprachvariante: HUD. RaceAssets.szs: zusätzliche RR-Elemente. Font.szs: allgemeine Schriften." }, new[] { "Menus|Title.szs: title/license. MenuSingle.szs: single player. MenuMulti.szs: multiplayer.", "Globe and background|Globe.szs: online menus. Earth.szs: globe scene/sky. globe.arc: globe colours. BackModel.szs: menu models.", "HUD and fonts|Race.szs and language variant: HUD. RaceAssets.szs: extra RR elements. Font.szs: general fonts." }, "Nur benötigte Dateien übernehmen und die ursprünglichen Dateinamen beibehalten.", "Install only needed files and retain their original filenames."),
                T("MKWii Game HUD Tool & Positionen", "MKWii Game HUD Tool & positions", "Menüelemente und Race-HUD-Layouts visuell bearbeiten.", "Visually edit menu elements and race HUD layouts.", "Tools → MKWii Game HUD Tool  /  MKWii Race HUD Tool → Move HUD visually", new[] { "Archiv und Layout wählen|MenuSingle.szs, Title.szs oder Common.szs öffnen. Die Layoutsuche filtert Dateinamen, etwa button oder select. Geteilte Texturen über Archiv hinzufügen laden.", "Visuell bearbeiten|Element anklicken und ziehen. Ganzes Layout verschieben aktivieren, um alle Kinder gemeinsam zu bewegen. Im Race HUD ist dies voreingestellt. Acht Ziehpunkte ändern die Größe; Umschalt hält die Proportionen. Bei Gruppen werden alle Kinder skaliert. Bildformat (16:9 oder 4:3) und Spieleransicht wählen. Verfügbare BRCTR-Positionen werden automatisch geladen. Der Bildschirmrahmen zeigt die zugehörige Bildschirmreferenz. Ohne BRCTR bleibt die Vorschau lokal. Die Renderauflösung des Spiels bleibt unverändert. Rechts Position, Skalierung, Drehung und Deckkraft einstellen. Mausrad zoomt; mit gedrückter Mausradtaste die Ansicht verschieben. Einpassen setzt Zoom und Ansicht zurück.", "Farben und Bilder|Elementfarbe färbt ein einzelnes Bild-/Textelement. Texturfarben ändert Grund- und Konturfarbe. Texturersatz betrifft alle Verwendungen derselben Texturdatei. Ein Referenzbild dient nur als Hintergrundhilfe.", "Übernehmen und testen|Rückgängig/Wiederholen ist verfügbar. Unten Archivkopien speichern. Im Race HUD zuerst übernehmen, anschließend dort die bearbeiteten Archive speichern und im Testing-Pack prüfen." }, new[] { "Choose archive and layout|Open MenuSingle.szs, Title.szs or Common.szs. Search filters layout filenames, e.g. button or select. Add archives to resolve shared textures.", "Edit visually|Click and drag an element. Enable Move whole layout to move all children together; this is the default in Race HUD. Use the eight handles to resize; hold Shift to keep proportions. Groups scale all children. Choose aspect ratio (16:9 or 4:3) and player view. Available BRCTR placements load automatically. The frame shows the corresponding screen reference; without BRCTR, the preview stays local. Game render resolution is unchanged. Adjust position, scale, rotation and opacity on the right. Mouse wheel zooms; hold the middle mouse button to pan the view. Fit view resets zoom and pan.", "Colours and images|Element tint colours a picture/text element. Texture colours edits base and outline colours. Replacing a texture affects all uses of the same file. Reference images are visual guides only.", "Apply and test|Undo/Redo is available. Save archive copies at the bottom. In Race HUD, apply first, then save the edited archives there and test your copies in your testing pack." }, "Die Vorschau zeigt ein statisches Teillayout, keinen vollständigen Spielbildschirm. Animationsziele sind markiert; Animationen und Spielcode können Änderungen überschreiben. Texte, 3D-Modelle und Materialeffekte sind nicht spielgetreu.", "The preview shows one static component layout, not a complete game screen. Animation targets are marked; animations and game code may override changes. Text, 3D models and material effects are not game-accurate."),
                T("Rückgängig & Sicherungen", "Undo & backups", "Auswahl zurücksetzen oder einen früheren Stand herstellen.", "Clear a selection or restore an earlier version.", "Undo  /  Original  /  Backup", new[] { "Vor dem Export|Undo entfernt die vorgemerkte Änderung des gewählten Elements.", "Originaloptionen|Originalfarben oder Originalmuster gelten für den nächsten Build aus der geöffneten Quelle.", "Nach dem Export|Bereits geschriebene Dateien mit deiner Sicherung wiederherstellen." }, new[] { "Before export|Undo removes the selected element's pending change.", "Original options|Original colours/pattern apply to the next build from the opened source.", "After export|Restore already written files from your backup." }, "Auswahl leeren setzt keine bereits exportierte Datei zurück.", "Clearing a selection does not revert an already exported file."),
                T("Prüfen & Vorschaugrenzen", "Checks & preview limits", "Was die Vorschau bestätigt – und was erst das Spiel zeigt.", "What a preview confirms, and what requires the game.", "Preview  →  Separate copy  →  In-game test", new[] { "Bild und Text|Texturvorschauen zeigen dekodierte Bilder. Textproben ersetzen nicht das tatsächliche Menü-Layout.", "Animation und 3D|Schematische Ansichten sind gekennzeichnet. GIF-Unterstützung hängt vom Zielbereich ab; Globus-GIFs nutzen acht Frames.", "Streckendaten|KMP/KCL über die Streckenprüfung validieren. Dafür muss Wiimms Toolchain verfügbar sein." }, new[] { "Images and text|Texture previews show decoded artwork. Text samples do not simulate the actual menu layout.", "Animation and 3D|Schematic views are labelled. GIF support depends on the target; globe GIFs use eight frames.", "Track data|Validate KMP/KCL using the track check. Wiimms tools must be available." }, "Zum Abschluss im separaten Testing-Pack prüfen. Teamfarben und Animationen können das Ergebnis beeinflussen.", "Finish by testing in a separate pack. Team colours and animations may affect the result."),
                T("Programm aktualisieren", "Update Studio", "Neue Versionen prüfen und installieren.", "Check for and install new versions.", "Help > Check for updates", new[] { "Automatisch prüfen|Beim Programmstart wird im Hintergrund nach Updates gesucht. Nur eine neuere verfügbare Version öffnet ein Fenster. Ohne Internet kannst du normal weiterarbeiten.", "Update installieren|Jetzt aktualisieren lädt den Installer herunter und prüft seine Prüfsumme. Speichere deine Änderungen und schließe Studio. Im Update-Fenster Install and restart wählen.", "Später fortfahren|Später schließt den Hinweis. Unter Hilfe > Nach Updates suchen kannst du jederzeit erneut prüfen." }, new[] { "Automatic check|Studio checks in the background at startup. Only a newer available version opens a window. You can keep working offline.", "Install an update|Update now downloads the installer and checks its checksum. Save your work and close Studio. In the update installer, choose Install and restart.", "Update later|Later dismisses the notification. You can check again under Help > Check for updates." }, "Projekte, Einstellungen und optionale Tools bleiben erhalten. Die erste öffentliche Beta benötigt einmalig den neuen Installer-Download.", "Projects, settings and optional tools are kept. The first public beta needs a one-time download of the new installer."),
                T("Links & Dokumentation", "Links & documentation", "Referenzen und zusätzliche Programme.", "References and specialist programs.", "Help / Toolchain", new[] { "Dokumentation & Credits|Die Projektseite unten enthält Anleitung und Downloads. Über das Info-Fenster öffnest du Credits und Lizenzen.", "Zusätzliche Programme|Tools > Toolchain zeigt Zweck, Installationsstatus und Pfad der Backends." }, new[] { "Documentation & credits|The project page below provides instructions and downloads. Open the About window for Credits and licenses.", "Additional programs|Tools > Toolchain shows each backend's purpose, installation status and path." }, "Die folgenden Links öffnen deinen Browser.", "The links below open your browser.")
            };
            topics[topics.Count - 1].IncludeLinks = true;
            return topics;
        }
    }
}
